// Override default JSON handling for WebAuthnOptions to handle AdditionalProperties
func (a WebAuthnOptions) MarshalJSON() ([]byte, error) {
	var err error
	object := make(map[string]json.RawMessage)

	object["publicKey"], err = json.Marshal(a.PublicKey)
	if err != nil {
		return nil, fmt.Errorf("error marshaling 'publicKey': %w", err)
	}

	for fieldName, field := range a.AdditionalProperties {
		object[fieldName], err = json.Marshal(field)
		if err != nil {
			return nil, fmt.Errorf("error marshaling '%s': %w", fieldName, err)
		}
	}
	return json.Marshal(object)
}

